INSERT INTO platform_rule_document(id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at)
SELECT '83ec2543c212491e8b6b9a24bc2800ce','rental_order_cancellation_refund_rule','幕间租赁订单取消与退款规则','2026.11','demander','html','<h2>幕间租赁订单取消与退款规则</h2><h3>适用范围</h3><p>本规则适用于租赁订单出库前的普通取消。待接单订单取消不扣租金；已出库订单不能普通取消，需要联系平台处理。工厂主动拒绝或两小时未接单的订单按原实付退款。</p><h3>取消费用</h3><p>已接单、未出库订单，以北京时间使用开始日00:00和服务器确认取消时间计算：超过48小时不扣租金；24至48小时（含24及48小时）扣原租金30%；不足24小时扣原租金60%。金额按分向下取整，实际扣款不得超过本单租金现金实付；优惠券抵扣不视为现金退款。</p><h3>退款与确认</h3><p>取消弹窗展示预计扣款、租金退款、押金退款、运费退款和合计。跨时间档位或订单状态变化须重新确认。押金和运费按原实付可退金额处理；退款按原支付渠道退回，实际到账时间以渠道为准，处理中可查询进度。整笔原支付全部现金退完且没有扣款时，优惠券按平台规则返还一次；有扣款或其他工厂尚未全退时不返券。</p><h3>适用版本</h3><p>订单采用提交时冻结的规则版本，后续规则更新不改变原单。</p>','a897f352b38cc5afa81132ca675c2f44837f7bf5fee3351b93abff318651718f',0,0,'active','2026-09-02 00:00:00.000',CURRENT_TIMESTAMP(3),CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS(SELECT 1 FROM platform_rule_document WHERE rule_code='rental_order_cancellation_refund_rule');
